278	/**
279	 * Where a route's view is: { views, template }, or { error }.
280	 * "orders/list" is the design's own (views/orders/list); "@app/<path>" is a
281	 * ported route's, the app's own file in the repository, read in place.
282	 */
283	export function viewOf({ folderPath, designDir, view, ext = '.eta' }) {
284	  if (!view.startsWith('@app/')) return { views: join(designDir, 'views'), template: `./${view}` };
285	  const file = normalize(join(folderPath, `${view.slice(5)}${extname(view) ? '' : ext}`));
286	  if (!file.startsWith(folderPath + sep)) return { error: `The view ${view} is outside the repository.` };
287	  if (!existsSync(file)) return { error: `There's no view at ${view} (looked for ${file.slice(folderPath.length + 1).split(sep).join('/')}).` };
288	  const base = file.slice(dirname(file).length + 1);
289	  return { views: dirname(file), template: `./${base.slice(0, base.length - extname(base).length)}` };
290	}
